export function translateResumeUi(text: string, language?: string): string {
    const lang = (language || 'en').toLowerCase().slice(0, 2) as ResumeLanguage;
    const translated = translations[lang]?.[text] ?? relatedSkillTranslations[lang]?.[text];
    if (translated) return translated;
    if (lang !== 'en' && text.startsWith('e.g. ')) {
        const examplePrefix: Record<Exclude<ResumeLanguage, 'en'>, string> = {
            tr: 'örn.', de: 'z. B.', es: 'p. ej.,', fr: 'ex.',
        };
        return `${examplePrefix[lang as Exclude<ResumeLanguage, 'en'>]} ${text.slice(5)}`;
    }
    return text;
}
